const GOAL = 8;
const NAVY = '#0f3550';
const MIST = '#e3f6ff';
const SKY = '#5ac8fa';
const DROP = 'M12 2.5s-7 7.6-7 12.3a7 7 0 0 0 14 0C19 10.1 12 2.5 12 2.5z';
const BOTTLE = 'M10 2h10v8l5 7v37a4 4 0 0 1-4 4H9a4 4 0 0 1-4-4V17l5-7z';

// The bottle fills toward the goal: 48 of its 60 units hold water.
function bottle(level, u) {
  const width = 34 * u;
  const height = 68 * u;
  const shape = (paint) => Object.assign({ type: 'path', d: BOTTLE, viewBox: [0, 0, 30, 60] }, paint);
  return { type: 'zstack', frame: { width, height }, children: [
    shape({ fill: '#FFFFFF1F' }),
    { type: 'zstack', frame: { width, height, alignment: 'bottom' }, mask: shape({ fill: '#FFFFFF' }), children: [
      level > 0 && { type: 'rect', fill: SKY, accent: true, frame: { width, height: height * 0.8 * level } } ] },
    shape({ stroke: { color: '#c9ecff', width: 2.2 * width / 30 } }),
  ] };
}

// The key's fill sits twice: solid in the backdrop, which tinted and clear mode remove, and faint in the tree.
// So in full color it reads as one solid key, and in tinted mode its words still show on the faint one.
function key(u, ghost) {
  return { type: 'zstack', padding: { leading: 15 * u, bottom: 15 * u },
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomLeading' },
    children: [
      { type: ghost ? 'zstack' : 'button', action: ghost ? null : 'drink', children: [
        { type: 'zstack', padding: { vertical: 7 * u, horizontal: 11 * u },
          background: { type: 'rect', cornerRadius: 10 * u, fill: ghost ? SKY : '#5ac8fa40' }, children: [
            { type: 'text', value: '+1 glass', size: 12.5 * u, weight: 'bold', color: NAVY, opacity: ghost ? 0 : 1 },
          ] } ] },
    ] };
}

function render(ctx) {
  // Sizes are in the prototype's units: a widget is 170 of them tall. Bricolage's line is 1.2 times its size, so
  // the gaps around the count are 0.1 of its size shorter than the prototype's.
  const u = ctx.height / 170;
  const d = ctx.data;
  const last = d.last;

  return {
    type: 'zstack', align: 'topLeading',
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    widgetBackground: { type: 'zstack', frame: { maxWidth: 'infinity', maxHeight: 'infinity' }, background: NAVY,
      children: [key(u, true)] },
    children: [
      { type: 'vstack', align: 'leading', spacing: 0,
        padding: { top: 15 * u, leading: 16 * u, trailing: 16 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
        children: [
          { type: 'hstack', spacing: 5 * u, frame: { height: 16 * u }, children: [
            { type: 'path', d: DROP, viewBox: [0, 0, 24, 24], fill: SKY, frame: { width: 15 * u, height: 15 * u } },
            { type: 'text', value: 'Water', size: 13 * u, weight: 'bold', color: SKY } ] },
          { type: 'text', value: d.today + '/' + GOAL, fontName: 'Bricolage Grotesque Display', size: 36 * u,
            kerning: -1.08 * u, color: MIST, accent: true, lineLimit: 1, minScale: 0.5, padding: { top: 4.4 * u },
            frame: { maxWidth: (ctx.width - 70 * u), alignment: 'leading' } },
          { type: 'text', value: d.today === 1 ? 'glass today' : 'glasses today', size: 12.5 * u,
            weight: 'semibold', color: MIST, opacity: 0.8, padding: { top: 1.4 * u } },
        ] },
      { type: 'zstack', padding: { top: 40 * u, trailing: 18 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topTrailing' },
        children: [bottle(Math.min(1, d.today / GOAL), u)] },
      last && last.minutesAgo < 10 && { type: 'zstack', padding: { top: 6 * u, trailing: 10 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topTrailing' },
        children: [
          { type: 'button', action: 'undo', rowId: last.id, children: [
            { type: 'symbol', name: 'arrow.uturn.backward', size: 12, weight: 'bold', color: MIST,
              frame: { width: 30, height: 30 }, background: '#e3f6ff22', clip: 'circle' } ] },
        ] },
      key(u, false),
    ],
  };
}
